import { Directive, ElementRef, inject } from '@angular/core';

/**
 * Transforms the value of a text input to uppercase as the user types.
 *
 * Works with Reactive Forms: reassigning `el.value` inside the native `input`
 * handler makes Angular's `DefaultValueAccessor` sync the bound `FormControl`
 * with the uppercased value. The caret position is preserved so typing in the
 * middle of the text does not jump the cursor to the end.
 *
 * ```html
 * <input type="text" formControlName="rfc" appUppercase>
 * ```
 */
@Directive({
  selector: '[appUppercase]',
  host: {
    '(input)': 'onInput()',
  },
})
export class UppercaseDirective {
  private readonly el = inject<ElementRef<HTMLInputElement>>(ElementRef).nativeElement;
  private syncing = false;

  onInput(): void {
    if (this.syncing) return;

    const upper = this.el.value.toUpperCase();
    if (upper === this.el.value) return;

    const start = this.el.selectionStart;
    const end = this.el.selectionEnd;

    this.el.value = upper;
    this.el.setSelectionRange(start, end);

    this.syncing = true;
    this.el.dispatchEvent(new Event('input', { bubbles: true }));
    this.syncing = false;
  }
}
